CREATE TABLE "clima_registro" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"momento" text NOT NULL,
	"apr_id" uuid,
	"execucao_id" uuid,
	"nivel" text NOT NULL,
	"titulo" text NOT NULL,
	"orientacao" text NOT NULL,
	"causas" jsonb DEFAULT '[]'::jsonb NOT NULL,
	"horas" jsonb DEFAULT '[]'::jsonb NOT NULL,
	"local_nome" text NOT NULL,
	"local_origem" text NOT NULL,
	"latitude" numeric(9, 6) NOT NULL,
	"longitude" numeric(9, 6) NOT NULL,
	"consultada_em" timestamp with time zone NOT NULL,
	"confirmou_apesar_do_aviso" boolean,
	"criado_por" uuid NOT NULL,
	"criado_em" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "clima_registro_momento_check" CHECK ("clima_registro"."momento" in ('apr', 'encerramento')),
	CONSTRAINT "clima_registro_nivel_check" CHECK ("clima_registro"."nivel" in ('sem_risco', 'atencao', 'extremo')),
	CONSTRAINT "clima_registro_origem_check" CHECK ("clima_registro"."local_origem" in ('aparelho', 'padrao')),
	CONSTRAINT "clima_registro_dono" CHECK (("clima_registro"."momento" = 'apr' and "clima_registro"."apr_id" is not null and "clima_registro"."execucao_id" is null) or ("clima_registro"."momento" = 'encerramento' and "clima_registro"."execucao_id" is not null and "clima_registro"."apr_id" is null)),
	CONSTRAINT "clima_registro_confirmacao_so_na_apr" CHECK ("clima_registro"."confirmou_apesar_do_aviso" is null or "clima_registro"."momento" = 'apr'),
	CONSTRAINT "clima_registro_latitude_check" CHECK ("clima_registro"."latitude" between -90 and 90),
	CONSTRAINT "clima_registro_longitude_check" CHECK ("clima_registro"."longitude" between -180 and 180)
);
--> statement-breakpoint
ALTER TABLE "clima_registro" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
