	"chave" text PRIMARY KEY NOT NULL,
	"valor" jsonb NOT NULL,
	"atualizado_em" timestamp with time zone DEFAULT now() NOT NULL,
	"atualizado_por" uuid,
	CONSTRAINT "configuracao_chave_check" CHECK ("configuracao"."chave" in ('cidade_padrao', 'sap_leitura_intervalo_min', 'rh_leitura_hora', 'email_resumo_hora', 'vitoria_limite_por_conversa', 'vitoria_limite_por_conta_dia', 'vitoria_limite_global_dia', 'vitoria_max_tokens_resposta', 'treinamento_ia_limite_treinamentos', 'treinamento_ia_limite_rodadas', 'treinamento_ia_max_tokens'))
);
